import { defineConfig } from 'vite';
import { resolve } from 'node:path';
import { practices } from './src/data/practice.js';
import { people } from './src/data/people.js';

const page = (section, slug) => [`${section}/${slug}`, resolve(__dirname, section, slug, 'index.html')];

// Fixed port so this project can run beside the other workspace dev servers.
// Sub-pages are generated by scripts/build-pages.mjs (npm pre-scripts) before Vite runs.
export default defineConfig({
  server: { port: 3270, strictPort: true },
  preview: { port: 3271, strictPort: true },
  build: {
    rollupOptions: {
      input: {
        main: resolve(__dirname, 'index.html'),
        contact: resolve(__dirname, 'contact', 'index.html'),
        notFound: resolve(__dirname, '404.html'),
        ...Object.fromEntries([
          ...practices.map((p) => page('practice', p.slug)),
          ...people.map((m) => page('people', m.slug)),
        ]),
      },
    },
  },
});
